function punch() {
  
  if (kb.presses('1') && fist.length == 0) {
    f = new fist.Sprite(player.x + 10, player.y);
   
    f.scale = 0.25
    f.mirror.x = true
    f.direction = player.direction
    f.vel.x = 5
    player.changeAni(['charge','idle'])
 

  }
  if (fist[0]) {
    if (dist(player.x, player.y, fist[0].x, fist[0].y) > 30) {
      fist[0].moveTowards(player, 0.03)
      fist.mirror.x = false
    }
     if (fist[0].overlapping(player) > 20) {
      fist[0].remove()

    }
    for(e of enemy){
    if (fist.overlapping(e)) {
      e.remove()

    }
  }
  for (let m of mosq) {
    if (fist.overlapping(m)) {
      m.changeAni('hurt');
      m.lives -= 1;
      if (m.lives <= 0) {
        m.remove();
      }
    }
  }
  }
}
