function drawText() {
  fill(232, 128, 200);
  text("Trophies: " + score2, 10, 260);
  text("Lumens: " + score, 10, 170);
//console.log(player.health)


  switch(player.health){
    case 3:// all lives
    fill(255,255,0)
    ellipse(250,50,50)
    ellipse(150,50,50)
    ellipse(50,50,50)
    stroke(255, 105, 180)
    strokeWeight(2)
    break;

    case 2:// minus one live
      fill(255,0,0)
      ellipse(250,50,50) 
      fill(255,255,0)
      ellipse(150,50,50)
      ellipse(50,50,50)
      break;
      case 1: // minus two lives
        fill(255,0,0)
        ellipse(250,50,50) 
        fill(255,0,0)
        ellipse(150,50,50)
        fill(255,255,0)
        ellipse(50,50,50)
        reset()
      break;
      case 0:// no lives
      reset()
      fill(255,0,0)
      ellipse(250,50,50) 
      fill(255,0,0)
      ellipse(150,50,50)
      fill(255,0,0)
      ellipse(50,50,50)
      reset();

      break;

  }
}

